import{_ as n,o as e,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Test — Guest sharing và Campaign do Manager quản lý","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/guest-sharing-manager-led/test.md","filePath":"feature/media-package-campaign/guest-sharing-manager-led/test.md"}'),h={name:"feature/media-package-campaign/guest-sharing-manager-led/test.md"};function r(c,t,o,g,l,d){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="test-—-guest-sharing-va-campaign-do-manager-quan-ly" tabindex="-1">Test — Guest sharing và Campaign do Manager quản lý <a class="header-anchor" href="#test-—-guest-sharing-va-campaign-do-manager-quan-ly" aria-label="Permalink to &quot;Test — Guest sharing và Campaign do Manager quản lý&quot;">​</a></h1><p>Ngày 2026-11-06. Kịch bản trước triển khai theo <a href="./spec.html">spec</a>, <a href="./plan.html">plan</a>, <a href="./task.html">task</a>. Trạng thái ban đầu: chưa chạy; chỉ đánh dấu pass khi có bằng chứng.</p><h2 id="moi-truong" tabindex="-1">Môi trường <a class="header-anchor" href="#moi-truong" aria-label="Permalink to &quot;Môi trường&quot;">​</a></h2><p>PostgreSQL và Mongo replica set cô lập; không dùng Atlas/production. Có Owner, Manager, Client và tài khoản khác Agency/workspace. Không publish thật hoặc gọi AI có phí. Giữ dữ liệu tham chiếu để so sánh trước/sau.</p><table tabindex="0"><thead><tr><th>ID</th><th>AC</th><th>Thao tác</th><th>Mong đợi</th></tr></thead><tbody><tr><td>S01</td><td>01,02</td><td>Owner phát hành link gói Agency; mở không đăng nhập</td><td>Chỉ nội dung gói; không membership/Client/history</td></tr><tr><td>S02</td><td>01,02</td><td>Manager share Custom Package workspace; mở guest trước khi mời Client</td><td>Đúng thỏa thuận workspace, không phải mẫu Agency</td></tr><tr><td>S03</td><td>02</td><td>Manager khác workspace/Client gọi API phát hành/export</td><td>Bị từ chối; không trả token hoặc nội dung</td></tr><tr><td>S04</td><td>03</td><td>Lưu sửa mẫu/gói workspace rồi tải lại link</td><td>Bản mới nhất của đúng gói; sửa mẫu không đổi gói workspace</td></tr><tr><td>S05</td><td>01,03,11</td><td>PDF/PNG gói dài, tiếng Việt, ký tự đặc biệt; giả lập lỗi renderer</td><td>Đủ trang/nội dung; file tại thời điểm xuất; lỗi không trả file thành công giả</td></tr><tr><td>S06</td><td>02,11</td><td>Thu hồi link, tạo lại, mở link cũ/sai</td><td>Không khả dụng; link mới xem được; không cache nội dung cũ</td></tr><tr><td>W01</td><td>04</td><td>Owner tạo workspace có Manager, không Client</td><td>Thành công; không redirect ép Client chọn/duyệt</td></tr><tr><td>W02</td><td>05</td><td>Manager chọn mẫu/tạo mới và lưu gói hợp lệ</td><td>Một Campaign DRAFT, một task TODO mỗi đơn vị; Manager mặc định</td></tr><tr><td>W03</td><td>06</td><td>Lặp cùng request/key; cùng key payload khác; hai save đồng thời</td><td>Không trùng Campaign/task; conflict có cấu trúc khi khác dữ liệu</td></tr><tr><td>W04</td><td>06</td><td>Crash sau SQL trước Mongo, sau một phần task, sau Mongo trước SQL</td><td>Operation bền vững; retry cùng ID; READY chỉ khi đủ task</td></tr><tr><td>W05</td><td>06</td><td>Worker mất lease, worker cũ quay lại; restart service</td><td>Không ghi lùi trạng thái/revision; operation mới không bị ghi đè</td></tr><tr><td>W06</td><td>07</td><td>Tăng số lượng/đổi tên gói; task đã sửa brief/assignee/deadline/comment</td><td>Giữ ID và thông tin đã nhập, chỉ thêm task còn thiếu</td></tr><tr><td>W07</td><td>07</td><td>Giảm/xóa/đổi loại làm mất task</td><td>Impact trả ID; khi chưa chứng minh an toàn thì chặn, không xóa/hủy dữ liệu</td></tr><tr><td>W08</td><td>06,07</td><td>Save khi đang preparation; stale terms version; retry sai revision</td><td>Conflict rõ; dữ liệu bản hiện hành giữ nguyên</td></tr><tr><td>C01</td><td>08</td><td>Mời Client sau; xem DRAFT và comment</td><td>Xem và góp ý được; không approve hoặc sửa kế hoạch</td></tr><tr><td>C02</td><td>09</td><td>Manager deploy kế hoạch đủ dữ liệu, không có approval</td><td>Deploy được; READY đúng revision bắt buộc</td></tr><tr><td>C03</td><td>09,10</td><td>Save/update campaign đồng thời deploy; retry failed deployment</td><td>Cố định bản; không chỉnh khi pending/failed; retry cùng version</td></tr><tr><td>C04</td><td>05,10</td><td>Creator bắt đầu Task khi Campaign DRAFT rồi IN_PROGRESS</td><td>DRAFT bị chặn, IN_PROGRESS tuân workflow hiện hành</td></tr><tr><td>C05</td><td>10</td><td>Task/Post approval, editor, Content Request, closure</td><td>Quyền và điều kiện module riêng giữ nguyên</td></tr><tr><td>C06</td><td>08</td><td>Feedback khi IN_PROGRESS/COMPLETED</td><td>Theo lifecycle feedback được hỗ trợ, không đổi Campaign hoặc mở lại</td></tr><tr><td>L01</td><td>10</td><td>Đọc lịch sử cũ, Campaign APPROVED/đang chạy</td><td>Giữ lịch sử; không reset/approval giả; mutation cũ không bypass khóa</td></tr><tr><td>D01</td><td>06,10</td><td>Fresh init và upgrade cùng fixture; chạy lại migration</td><td>Cùng schema/index; không xóa dữ liệu ngoài phạm vi</td></tr><tr><td>D02</td><td>05,10</td><td>Seeder chạy lại</td><td>Dataset đúng flow mới; không trùng dữ liệu; Task metadata hợp lệ</td></tr><tr><td>U01</td><td>11</td><td>Loading/empty/error/offline/conflict/failed preparation</td><td>Skeleton hoặc trạng thái tương ứng; giữ draft nhập; retry có nghĩa</td></tr><tr><td>U02</td><td>12</td><td>Chuyển vi/en trên các màn share/guest/workspace/campaign</td><td>Không thiếu key, không hardcode hoặc vỡ bố cục</td></tr><tr><td>U03</td><td>12</td><td>Light/dark, mobile, tab/keyboard/dialog focus</td><td>Contrast rõ, action truy cập được, không tràn ngang</td></tr></tbody></table><h2 id="failure-matrix-can-ghi-ket-qua" tabindex="-1">Failure matrix cần ghi kết quả <a class="header-anchor" href="#failure-matrix-can-ghi-ket-qua" aria-label="Permalink to &quot;Failure matrix cần ghi kết quả&quot;">​</a></h2><p>Mỗi W03–W08/C03 phải ghi trạng thái SQL, task IDs/count và dữ liệu người dùng trước/sau. Không kết luận atomic xuyên hai DB. Lỗi một phần phải có preparation status và đường retry; không dùng xóa bù toàn bộ task.</p><h2 id="ket-qua-thuc-thi" tabindex="-1">Kết quả thực thi <a class="header-anchor" href="#ket-qua-thuc-thi" aria-label="Permalink to &quot;Kết quả thực thi&quot;">​</a></h2><h3 id="đa-xac-minh-ngay-2026-11-06" tabindex="-1">Đã xác minh ngày 2026-11-06 <a class="header-anchor" href="#đa-xac-minh-ngay-2026-11-06" aria-label="Permalink to &quot;Đã xác minh ngày 2026-11-06&quot;">​</a></h3><ul><li>Business: bộ <code>service.*Package*Test</code>, <code>service.*Campaign*Test</code>, <code>service.impl.*Test</code>, <code>seed.*Test</code> chạy cùng <code>BRANDHUB_PACKAGE_QA=true</code>: 432 test, 0 failure/error, 12 test có điều kiện khác bị skip. Bao gồm test tích hợp mới, không khởi động application hoặc dùng cấu hình <code>.env</code>.</li><li>Sau lượt tổng thể, bổ sung và chạy lại 5 test share/export (pass), gồm kiểm tra export Agency không dùng SELECT FOR UPDATE trong transaction chỉ đọc.</li><li>Test SQL/Mongo dùng hai container QA riêng ở cổng 55439/57019: hai save đồng thời cùng key trả cùng Campaign; task đủ số lượng; crash giả lập sau Mongo trước READY phục hồi qua lease hết hạn; giữ description/workflowRevision đã sửa; không tăng số task hoặc tạo lại version; issue/revoke workspace link hợp lệ.</li><li>Gateway: <code>RateLimitGatewayFilterFactoryTest</code> và <code>LoggingGlobalFilterTest</code>: 13 test pass. Guest rate limit theo IP không cần X-User-Id và không tin header giả; public mode không mở route workspace.</li><li>Web: <code>npm run build</code> và type-check pass. ESLint các file thay đổi: 0 error; một warning có sẵn ở AuthGuard về setState trong effect. Bundle lớn của module có sẵn còn cảnh báo, không chặn build.</li><li>Locale mediaPackage/campaign key-parallel vi/en. Workspace còn hai key plural lệch sẵn trên HEAD (<code>list.members_other</code>, <code>list.posts_other</code>), đợt này không làm tăng số key lệch.</li><li>PostgreSQL QA: fresh init khai báo schema cuối chạy được; init HEAD cũ + migration mới chạy được; migration chạy lại được. Đối chiếu 47 cột/kiểu/nullability/default của ba bảng liên quan giữa fresh và upgrade khớp nhau.</li><li>Trình duyệt local: route guest mở khi chưa đăng nhập và hiển thị đúng trạng thái link không khả dụng, không redirect login. Chưa manual toàn bộ flow trên tài khoản thật vì chưa APPLY schema vào DB ứng dụng.</li></ul><h3 id="chua-coi-la-đa-hoan-tat" tabindex="-1">Chưa coi là đã hoàn tất <a class="header-anchor" href="#chua-coi-la-đa-hoan-tat" aria-label="Permalink to &quot;Chưa coi là đã hoàn tất&quot;">​</a></h3><ul><li>Ma trận UI vi/en/light/dark/mobile/keyboard và luồng đầy đủ qua HTTP với các tài khoản Owner/Manager/Client sau migration/restart.</li><li>Phối hợp mobile/client cũ và nghiệm thu với chủ module Task/Post/publishing.</li><li>Giảm/xóa/đổi loại làm mất task hiện có đang được chặn theo phương án an toàn; chưa hỗ trợ xác nhận để xóa task nguyên bản.</li><li>Bản export ban đầu là PDF ảnh. Đã được thay bằng PDF text/vector trong mục nghiệm thu format bên dưới; PNG tiếp tục tải theo bộ ZIP.</li><li>Chưa APPLY schema hoặc ghi seed trên PostgreSQL demo, Atlas hay production. Chưa deploy/restart các service dùng DB ứng dụng.</li></ul><p>Các container QA và file baseline tạm được dọn sau kiểm thử. Không có request AI có phí, publish thật hoặc thao tác AWS trong lượt này.</p><h2 id="nghiem-thu-format-proposal" tabindex="-1">Nghiệm thu format proposal <a class="header-anchor" href="#nghiem-thu-format-proposal" aria-label="Permalink to &quot;Nghiệm thu format proposal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Input/Thao tác</th><th>Kết quả cần đạt</th></tr></thead><tbody><tr><td>E01</td><td>Gói 3-4 dịch vụ, có ngân sách/thời lượng</td><td>Thứ tự đọc rõ; bảng hạng mục/cột số lượng không đè chữ; không có enum nội bộ</td></tr><tr><td>E02</td><td>Không ngân sách/thời lượng hoặc không mô tả</td><td>Không biến thành 0, không tạo phần trống lớn hoặc cam kết giả</td></tr><tr><td>E03</td><td>Mô tả/tiêu chí dài, nhiều đoạn và dấu tiếng Việt</td><td>Không thiếu chữ/cắt dòng; continuation rõ; không tiêu đề lẻ/trang trắng cuối</td></tr><tr><td>E04</td><td>Tên gói/Agency 255 ký tự, đơn vị dài, URL không khoảng trắng</td><td>Wrap trong vùng nội dung, không tràn lề hoặc footer</td></tr><tr><td>E05</td><td>Xuất vi/en cùng dữ liệu</td><td>Nhãn đúng ngôn ngữ, text do người dùng nhập giữ nguyên, không trộn nhãn song ngữ</td></tr><tr><td>E06</td><td>Đọc PDF text bằng PdfTextExtractor/Poppler và đối chiếu PNG ZIP</td><td>PDF chọn/copy được tiếng Việt; số trang ảnh/PDF trùng; nội dung cuối vẫn có</td></tr><tr><td>E07</td><td>Số lượt sửa 0, giá trị null</td><td>0 được thể hiện đúng, null không tự suy thành 0</td></tr><tr><td>E08</td><td>Render và xem trang đầu, trang tiếp tục, trang cuối ở 96–110 dpi, ảnh xuất thật ở 1240 × 1754</td><td>Không overlap, glyph lỗi, mất dấu, bảng cắt ngang hoặc footer lẫn body</td></tr></tbody></table><p>Kết quả format ngày 2026-11-06:</p><ul><li><p><code>PackageExportRendererTest</code> (5) và <code>PackageProposalLayoutTest</code> (1): pass. Kiểm tra PDF text tiếng Việt/NFC, enum thành nhãn, vi/en, null/0, PDF/PNG cùng số trang, nội dung dài và vùng biên tên/URL/đơn vị dài.</p></li><li><p>Đã xem trực tiếp toàn bộ mẫu vi (2 trang), en (2 trang), gói dài (5 trang), mẫu không giá/thời lượng (1 trang), và PNG thực tế từ bộ ZIP. Poppler render 96–110 dpi; PNG xuất 1240 × 1754. Không thấy overlap, mất dấu, cắt chữ hoặc footer đè nội dung. Gói ít nội dung có khoảng trắng chủ đích, không thêm nội dung giả để lấp trang.</p></li><li><p>Web type-check và ESLint riêng <code>PackageShareActions.tsx</code>: pass. Ngôn ngữ export theo locale hiện hành.</p></li><li><p>Artifact QA lưu trong <code>keep-local-only/proposal-export-qa</code>, không đưa vào Git. Không cần migration/init/seeder vì thay đổi chỉ ở renderer và query language tùy chọn.</p></li><li><p>Chưa kiểm thử tải file qua phiên đăng nhập HTTP sau restart Business; không coi unit test là nghiệm thu toàn bộ hành trình UI.</p></li><li><p>Hồi quy cuối: <code>PackageExportRendererTest</code>, <code>PackageProposalLayoutTest</code>, <code>MediaPackageShareServiceTest</code>, <code>WorkspacePackagePlanningServiceTest</code>: tổng 16 test, 0 failure/error/skip. Lượt chạy ngoài sandbox pass; lượt sandbox ban đầu bị chặn Mockito JVM attach (named pipe), không phải lỗi nghiệp vụ.</p></li></ul><h3 id="kiem-chung-sau-review-nhan-export" tabindex="-1">Kiểm chứng sau review nhãn export <a class="header-anchor" href="#kiem-chung-sau-review-nhan-export" aria-label="Permalink to &quot;Kiểm chứng sau review nhãn export&quot;">​</a></h3><p>Đã bỏ nhãn đề xuất, cột lượt sửa và các chú thích được yêu cầu. Kiểm tra PDF text xác nhận nhãn mới, câu số lượng tự nhiên và không còn các nhãn cũ ở cả vi/en. <code>PackageExportRendererTest</code> (5) + <code>PackageProposalLayoutTest</code> (1): 6 test pass, 0 failure/error. Đã xem lại hai trang PDF vi và PNG xuất thật; xem tổng thể các trang dài/en/thiếu giá để kiểm tra phân trang. Không đổi DB hoặc giá trị revisionLimit; chỉ bỏ hiển thị trong export.</p><h3 id="bao-đien-tu-—-lam-ro-cach-hien-thi-cho-client" tabindex="-1">Báo điện tử — làm rõ cách hiển thị cho Client <a class="header-anchor" href="#bao-đien-tu-—-lam-ro-cach-hien-thi-cho-client" aria-label="Permalink to &quot;Báo điện tử — làm rõ cách hiển thị cho Client&quot;">​</a></h3><p>Bản xem gói/card/guest chứa PRESS_RECOMMENDATION quantity=3 unit=danh sách đề xuất phải hiện “3 bài” và “Bài báo điện tử”; en là articles/Online press articles. Export phải hiện “3 bài báo điện tử”, không hiện recommendation list ở cột unit; mô tả do người dùng nhập giữ nguyên. Không mutation dữ liệu, không đổi Task type. Text dùng t(), không đổi CSS/theme/focus.</p><p>Kết quả: 6 test export/layout pass, locale vi/en và plural unit pass; xem trực tiếp hai trang PDF mẫu mới. Type-check toàn Web dừng ở GuidePage.tsx (Database, Hash và t không được dùng), không thuộc thay đổi này. Không sửa dữ liệu cũ hoặc schema/enum/workflow.</p><p>ESLint hai component OfferingSummary/MediaPackageCard: pass. Chỉ đổi nhãn/unit hiển thị; tên và mô tả hạng mục người dùng đã nhập không bị ghi đè.</p><h3 id="xuat-anh-trang-đau-theo-xac-nhan" tabindex="-1">Xuất ảnh trang đầu theo xác nhận <a class="header-anchor" href="#xuat-anh-trang-đau-theo-xac-nhan" aria-label="Permalink to &quot;Xuất ảnh trang đầu theo xác nhận&quot;">​</a></h3><p>Với gói PDF nhiều trang: Xuất ảnh trả JPEG magic FF D8, decode được 1240x1754, không ZIP và chỉ trang đầu. Controller trả image/jpeg và .jpg; Web tải .jpg. PDF giữ số trang và nội dung cuối. Format ảnh mới là jpg, không còn ZIP. File ảnh được xem trực tiếp, không crop nhầm trang.</p><p>Kết quả JPG: 6 test renderer/layout pass; JPEG thực có FF D8, decode 1240×1754, PDF mẫu vẫn nhiều trang và giữ nội dung cuối. Đã xem trực tiếp JPG xuất thật, chỉ trang đầu. Web type-check và ESLint PackageShareActions pass. Chưa kiểm tra tải qua phiên HTTP thật sau restart; không cần migration.</p><h3 id="ban-xem-theo-format-proposal" tabindex="-1">Bản xem theo format proposal <a class="header-anchor" href="#ban-xem-theo-format-proposal" aria-label="Permalink to &quot;Bản xem theo format proposal&quot;">​</a></h3><p>Kiểm tra 3 route dùng cùng component. Dữ liệu 3 dịch vụ có budget/duration: thứ tự giống PDF, không cột lượt sửa, không hướng dẫn dư, chi tiết mở sẵn; press= bài báo điện tử. Không giá/thời lượng: trao đổi thêm, không 0. Tên/mô tả dài wrap không cắt. vi/en đúng nhãn, dark/light đủ contrast, mobile 390px không tràn trang, bảng còn đọc được. Back/share/edit/guest loading/error giữ nguyên. Không sửa DB/API.</p><p>Kết quả bản xem proposal: type-check pass; lint các file tích hợp và component pass. Playwright trên fixture local đã kiểm tra 24 tổ hợp (normal/missing/long × vi/en × light/dark × 390/1440px), không page error hoặc document overflow; đã xem trực tiếp ảnh desktop vi/light, en/dark và mobile vi/dark. Không có API/DB được gọi trong fixture; chưa coi đây là kiểm thử HTTP đầy đủ qua các tài khoản thật. Back/share/edit và query/loading/error hiện hành giữ nguyên; 3 route tích hợp dùng cùng component. Nhãn/unit dịch vụ chuẩn hóa vi/en. Artifact và browser QA ở keep-local-only, không đưa Git.</p><p>Production build local pass; còn cảnh báo chunk Agora lớn có sẵn. Không deploy hoặc thao tác AWS. Đã đóng browser QA và Vite fixture sau kiểm tra.</p><h3 id="workspace-package-—-overview-gon-va-share-menu" tabindex="-1">Workspace package — overview gọn và share menu <a class="header-anchor" href="#workspace-package-—-overview-gon-va-share-menu" aria-label="Permalink to &quot;Workspace package — overview gọn và share menu&quot;">​</a></h3><p>Kiểm tra current card trái/catalog phải, chọn card mở proposal full width và Back về card; Space/Enter xem, Tab đến action không vô tình mở card. Icon share mở menu, JPG/PDF/link đúng request và filename; mặc định không gọi API share/export, revoke vẫn riêng. Client xem catalog nhưng không select/edit/share; locked manager vẫn xem nhưng không sửa/chọn; missing/error/pending không bypass khóa; FAILED vẫn retry. Không banner LEGACY hoặc link Campaign. Sáng/tối và mobile 390px không tràn; vi/en key parity, title dài wrap. Dùng mock local, không ghi API/DB thật.</p><p>Kết quả Workspace overview: type-check, lint 6 file thay đổi và production build local pass (cảnh báo chunk Agora lớn có sẵn). Playwright fixture tích hợp WorkspaceMediaPackagePage với API mock: catalog tự tải; không CTA Campaign/banner LEGACY; card hiện tại và card khác mở proposal full width/Back; Enter mở card; chọn gói mở form đã điền mà không mở detail; menu share không mở card, tải JPG/PDF đúng format/filename, copy link gọi đúng API mock; keyboard Enter/Escape trả focus về share. Client không có edit/select/share, Manager DEPLOYED không sửa/chọn, PENDING/FAILED bị khóa sửa. Kiểm tra 8 tổ hợp vi/en × light/dark × 390/1440, không tràn ngang/page error; đã xem screenshot vi/light desktop và vi/dark mobile. Không gọi API thật/ghi DB, không submit lưu form hoặc APPLY migration. QA/download/mock và ảnh nằm keep-local-only, không đưa Git. Chưa kiểm thử save thật hoặc HTTP phân quyền Backend trong lượt UI này.</p><h3 id="sketch-đuoc-duyet-—-detail-trai-list-phai" tabindex="-1">Sketch được duyệt — detail trái, list phải <a class="header-anchor" href="#sketch-đuoc-duyet-—-detail-trai-list-phai" aria-label="Permalink to &quot;Sketch được duyệt — detail trái, list phải&quot;">​</a></h3><p>Mặc định hiện proposal current bên trái và current card đầu bên phải. Click card khác giữ list/card focus, đổi proposal trái và aria-pressed; current badge không chuyển. Search không ẩn current card; xóa search khôi phục list; thêm 12 cho catalog dài. Desktop scroll trái không dịch list/header hoặc body, scroll list không dịch proposal; mobile không tràn và vẫn chọn được gói. Gói mất khỏi catalog fallback hợp lệ. Client không select/edit/share; locked manager không sửa/chọn. Form cuộn được; share menu giữ formatjpg/pdf. Không mutation ngoài mock QA.</p><p>Kết quả sketch: type-check/lint pass. Playwright trên fixture tích hợp có header và main giới hạn chiều cao như app: detail trái, list phải; current ghim thứ tự đầu, mặc định xem current; click/Enter đổi proposal không điều hướng, aria-pressed phân biệt đang xem; cuộn detail 350px không đổi list và ngược lại; body desktop không cuộn. Tìm kiếm giữ card current, load more mở đủ 22 gói QA; JPG/PDF request và filename đúng. Client không có edit/select/share, Manager DEPLOYED không sửa/chọn; 8 tổ hợp vi/en × light/dark × 390/1440 không tràn ngang/page error. Đã xem trực tiếp ảnh desktop vi/light và mobile vi/dark, xác minh mobile cuộn tới cuối chi tiết được. State xem gắn Workspace ID, dữ liệu xem lấy từ query mới; ID mất thì fallback current/catalog. Không API thật, DB hay AWS. QA nằm keep-local-only.</p><p>Build cuối sau tất cả sửa đổi pass, chỉ cảnh báo bundle lớn có sẵn. Đã đóng browser QA/Vite fixture. Không commit/push hoặc deploy.</p><h3 id="sketch-compact-đuoc-duyet-—-mo-ta-ngan-va-bang-mo-chi-tiet" tabindex="-1">Sketch compact được duyệt — mô tả ngắn và bảng mở chi tiết <a class="header-anchor" href="#sketch-compact-đuoc-duyet-—-mo-ta-ngan-va-bang-mo-chi-tiet" aria-label="Permalink to &quot;Sketch compact được duyệt — mô tả ngắn và bảng mở chi tiết&quot;">​</a></h3><p>Fixture 3 dịch vụ với mô tả dài: mặc định chỉ header, metadata, mô tả 2 dòng và 3 hàng; không section chi tiết lặp, không wordmark/factcards. Ở viewport desktop thông thường pane detail scrollHeight&lt;=clientHeight. Click Xem đúng hàng mở mô tả/mục tiêu, Xem thêm hiện chỉ khi đo tràn 2 dòng; Thu gọn hoạt động, full text giữ nguyên. Resize cập nhật overflow; đổi gói reset state. Hàng thiếu details không mở action rỗng. Keyboard Enter/Space, aria-controls/expanded và nút có tên gắn hạng mục. Mobile không tràn ngang, nội dung dài đọc hết sau mở/scroll; client/locked không đổi quyền; search/list/share giữ nguyên. Fixtures/read-only mock, không mutation DB.</p><p>Kết quả compact: type-check, ESLint 4 component và build cuối pass (còn warning chunk lớn có sẵn). Playwright fixture mock 3 hạng mục ở desktop 1440×900: detail clientHeight=scrollHeight=753px, không cần cuộn mặc định; title computed 18px. Đã xác minh mô tả tối đa 2 dòng, chỉ text tràn có Xem thêm; mở/thu gọn mô tả và từng hàng, keyboard Enter, aria-expanded/controls đúng; text ngắn không có nút dư, hạng mục không có details không có action rỗng; đổi gói reset trạng thái mở. Budget/duration null vẫn “Trao đổi thêm”. Share JPG đúng API/filename mock, Client và Manager locked giữ quyền. 8 tổ hợp vi/en × light/dark × 390/1440 không tràn ngang, không page error; đã xem trực tiếp vi/light desktop, vi/dark mobile, en/dark desktop. Không cam kết không cuộn khi gói quá nhiều hạng mục hoặc người dùng mở text dài. PDF/JPG renderer, API và DB không thay đổi; chưa manual HTTP save trên dữ liệu thật. QA được giữ trong keep-local-only và không đưa Git.</p><h3 id="ui-v3-đa-duyet-—-cam-nhat-xam-trang-va-noi-dung-theo-khong-gian" tabindex="-1">UI v3 đã duyệt — cam nhạt, xám/trắng và nội dung theo không gian <a class="header-anchor" href="#ui-v3-đa-duyet-—-cam-nhat-xam-trang-va-noi-dung-theo-khong-gian" aria-label="Permalink to &quot;UI v3 đã duyệt — cam nhạt, xám/trắng và nội dung theo không gian&quot;">​</a></h3><p>Header table dùng brand-orange-soft, detail nền muted/field bg-card; edit Button orange và share gray; không tên hạng mục lặp trong detail. Short description 3–5 dòng vẫn hiện đủ sau Xem nếu vừa pane (không bị ép 2 dòng). Long row làm tràn thì có Xem thêm, mở đủ và thu gọn được. Resize và đổi locale không gây loop/page error. Mở nhiều hàng không tự đổi quyết định/permission; explicit expand cho phép scroll. Kiểm tra selected/viewed card, share download/mock, Client/locked, responsive 390/1440, chữ vẫn 18/14. QA local mock, không ghi DB thật.</p><p>Kết quả UI v3: type-check và lint 7 file thay đổi pass. Playwright QA tích hợp Workspace page dùng mock: xác minh computed colors table/header/action/card đúng token, detail row xám + field trắng, không title lặp. Text 4 dòng hiện đủ nếu vừa pane; long text fallback có Xem thêm và mở/thu gọn được. Resize hai chu kỳ 1440×420 ↔ 1440×1100 không loop/page error, aria và keyboard đúng, đổi gói reset row. Mobile long text dùng viewport thực thay vì chiều cao nội dung tự giãn, có thể mở đủ thủ công, không tràn ngang. Client/locked giữ điều kiện action; JPG download mock đúng filename. 8 tổ hợp vi/en × sáng/tối × 390/1440 pass; đã xem trực tiếp ảnh vi/light với hai hàng mở và vi/dark mobile. Default 3 hàng vẫn không cần cuộn desktop. Chưa kiểm thử HTTP save thật; không DB/API/export renderer/migration hoặc AWS thay đổi. QA và hình ảnh được giữ trong keep-local-only, không đưa Git.</p><p>Build cuối sau chỉnh adaptive mobile pass; còn cảnh báo bundle lớn có sẵn. Browser QA và Vite fixture đã đóng. Chưa commit/push hoặc deploy.</p><h3 id="so-luong-đau-hang-va-tu-mo-hang-muc-khi-co-cho" tabindex="-1">Số lượng đầu hàng và tự mở hạng mục khi có chỗ <a class="header-anchor" href="#so-luong-đau-hang-va-tu-mo-hang-muc-khi-co-cho" aria-label="Permalink to &quot;Số lượng đầu hàng và tự mở hạng mục khi có chỗ&quot;">​</a></h3><p>3 hạng mục ngắn đủ chỗ: chi tiết có dữ liệu tự mở khi chọn gói, không cần click Xem; title không lặp. Cột đầu là quantity+unit, không còn #/STT và quantity cột khác. Bấm tên/số lượng/native Xem đều toggle đúng 1 lần, Enter/Space và aria đúng. Đóng thủ công không bị observer mở lại. Gói dài chỉ auto mở hàng vừa budget, mở thủ công vẫn đọc hết qua Xem thêm; nhiều hàng không auto overflow. Đổi gói/reset, resize/locale không loop, search/current top/share/Client/locked còn đúng. Mock local, không ghi dữ liệu thật.</p><p>Kết quả: build/type-check và ESLint 4 file pass; git diff --check pass. Playwright local mock xác minh 3 hàng ngắn tự mở, desktop pane clientHeight=scrollHeight=753px; hàng dài bỏ qua tự mở nhưng hàng ngắn phía sau vẫn mở; 18 hàng không tự làm tràn. Click tên/số lượng/button/Space toggle một lần; manual close giữ khi resize, đổi gói reset. 8 tổ hợp vi/en × sáng/tối × 390/1440 không page error hoặc tràn ngang. Share JPG mock và Client/Manager locked pass. Đã xem screenshot desktop. Không sửa DB/API, không chạy trên production; QA trong keep-local-only.</p><h3 id="pdf-va-jpg-theo-sketch-duyet-06-11-2026" tabindex="-1">PDF và JPG theo sketch duyệt 06/11/2026 <a class="header-anchor" href="#pdf-va-jpg-theo-sketch-duyet-06-11-2026" aria-label="Permalink to &quot;PDF và JPG theo sketch duyệt 06/11/2026&quot;">​</a></h3><p>Kiểm tra 3 hạng mục ngắn thành overview+detail; thứ tự quantity/name, không STT/hướng dẫn; metadata vắng không bịa giá. Long text giữ sentinel cuối, không vượt printable area. JPG hai trang đặt cạnh nhau; nhiều trang nối hàng không mất trang; vượt pixel budget trả lỗi có cấu trúc thay vì OOM. QA artifact chỉ trong keep-local-only, không DB/AWS.</p><p>Kết quả: Maven compile/test pass, 8 test (PackageExportRendererTest + PackageProposalLayoutTest), không DB/service ngoài. PDF vi/en mẫu 2 trang, null 1 trang, long 5 trang và nhiều hạng mục 5 trang; text cuối không mất, text nằm trong printable area. JPG 2 trang 2540×1794; tài liệu nhiều trang giữ đủ từng tile theo thứ tự trái→phải, trên→dưới. Pixel budget 24 triệu (tối đa 10 trang A4 ở scale hiện tại), vượt trả PACKAGE_EXPORT_FAILED trước cấp phát, vẫn xuất PDF và slot được giải phóng. Đã render/rà soát ảnh PDF/JPG, long/many contacts; không tràn/chồng chữ, dấu Việt đọc được. Preview/log chỉ keep-local-only. Không sửa DB/migration, không AWS/deploy, chưa thử HTTP authenticated export thật.</p><h3 id="chon-ngon-ngu-khi-xuat-file" tabindex="-1">Chọn ngôn ngữ khi xuất file <a class="header-anchor" href="#chon-ngon-ngu-khi-xuat-file" aria-label="Permalink to &quot;Chọn ngôn ngữ khi xuất file&quot;">​</a></h3><p>Mock export API local: website VI xuất EN và ngược lại, đủ pdf/jpg × vi/en; request đúng format/language, filename có mã ngôn ngữ. Không phát sinh request chỉ mở menu. Arrow/Enter/Escape và click mobile dùng được; copy/revoke giữ nguyên. Không dịch nội dung người dùng.</p><p>Kết quả: ESLint component và production build/type-check pass. Playwright API mock pass 8 lượt download (4 tổ hợp × website VI/light/1440 và EN/dark/390); format/language và filename khớp, không thêm request ngoài 8 export. ArrowRight mở submenu, Escape thoát; menu có font/màu đúng theme. Không page error; artifacts trong keep-local-only. Backend vi/en PDF/JPG đã qua 8 test bộ xuất ở thay đổi trước; không sửa DB hoặc HTTP dữ liệu thật.</p><h3 id="ngon-ngu-trang-guest" tabindex="-1">Ngôn ngữ trang guest <a class="header-anchor" href="#ngon-ngu-trang-guest" aria-label="Permalink to &quot;Ngôn ngữ trang guest&quot;">​</a></h3><p>Fixture guest public API mock không đăng nhập. Đổi VI→EN: Budget/Duration/Quantity/units đổi, tên/mô tả gốc giữ nguyên, API không fetch lại do đổi locale; reload giữ EN. Error/retry và skeleton vẫn có selector; không overflow ngang ở 390, aria-pressed/keyboard đúng.</p><p>Kết quả: focused ESLint + production build/type-check pass. Browser local mock pass: switch labels, pressed state, nội dung gốc giữ nguyên, không refetch khi đổi ngôn ngữ, persist qua reload, selector có ở loading/error/retry, keyboard Enter, 4 tổ hợp 390/1440 sáng/tối không tràn ngang và không pageerror. Không DB/API/production thay đổi; fixture/artifact trong keep-local-only.</p><h3 id="form-nhap-lieu-theo-sketch-đa-duyet" tabindex="-1">Form nhập liệu theo sketch đã duyệt <a class="header-anchor" href="#form-nhap-lieu-theo-sketch-đa-duyet" aria-label="Permalink to &quot;Form nhập liệu theo sketch đã duyệt&quot;">​</a></h3><p>Browser mock only. Mỗi service tối đa một row mới; bật/tắt/bật giữ ID và draft; chuyển editor giữ text. Suggestion thêm/bỏ đúng đoạn và không mất nội dung riêng, locale change không làm mất khả năng bỏ đoạn đã chọn, max2000. Input số không 003, budget10/25/50m duration2/4/6/8, vẫn blank null; submit đúng API không mock data. Lỗi field ở hàng khác phải focus đúng editor; uncheck không submit dữ liệu disabled. Legacy giữ nguyên. Dirty/discard, sticky save không che cuối form, reduced-motion, mobile/no overflow, lint/type/build.</p><p>Kết quả: Web CI lint/type-check/build pass (cảnh báo lint/chunk có sẵn), focused lint 5 file và build cuối pass. Browser form thật với mock submit: 4 service không tạo trùng, giữ ID gốc và draft qua toggle, suggestion thêm/bỏ giữ text riêng và bỏ đúng đoạn sau đổi locale, 003 chuẩn hóa về 3, budget quick/custom/null và duration optional, loading disabled. Native validation ở panel ẩn mở/focus đúng, whitespace name và qty0 chặn submit; create blank và legacy/duplicate có sẵn giữ dữ liệu. 8 tổ hợp vi/en × light/dark ×390/1440 không overflow/pageerror, footer hiện và cuối textarea cuộn đọc được. Tích hợp Workspace mock mở form một tiêu đề, back dirty mở dialog. Preview/test artifacts chỉ keep-local-only; chưa HTTP save thật, không DB/API/production thay đổi. Các thay đổi Admin/graph xuất hiện đồng thời ngoài phạm vi được giữ nguyên.</p><h3 id="sua-thanh-luu-đe-noi-dung" tabindex="-1">Sửa thanh Lưu đè nội dung <a class="header-anchor" href="#sua-thanh-luu-đe-noi-dung" aria-label="Permalink to &quot;Sửa thanh Lưu đè nội dung&quot;">​</a></h3><p>So sánh rect vùng cuộn/footer không chồng lên nhau tại scroll0/giữa/cuối; có thể focus/cuộn tới textarea cuối nằm trên footer. Resize desktop/mobile, footer Hủy/Lưu nằm trong viewport, không tràn ngang. Gói nhiều nội dung không làm mất action, submit payload giữ nguyên.</p><p>Kết quả QA local mock: vùng cuộn bottom &lt;= footer top ở scroll đầu/giữa/cuối trên 1440×900,1440×600,390×800,390×600; footer nằm trong viewport, textarea cuối cuộn đọc đủ. Đã xem ảnh desktop/mobile. Regression form: 4 service/ID/draft/suggestion/locale/hidden validation/optional/loading và 8 tổ hợp vi/en light/dark 390/1440 pass; submit fixture không API thật. Focused ESLint không warning/error. Không đổi DB/BA/API hoặc commit, giữ nguyên các chỉnh sửa đồng thời ở Admin/client-profiles.</p><p>Build cuối bị chặn bởi thay đổi đồng thời ngoài phạm vi: AgencyBrandingSection.tsx thiếu COLOR_SWATCHES/implicit any và agency/create.tsx truyền brandColor không có trong props. Không sửa các file Agency này. Build trước đó của bản footer đầu đã pass; bản cuối focused lint + browser regression pass.</p><h3 id="thu-gon-vung-tieu-đe-va-thao-tac-luu" tabindex="-1">Thu gọn vùng tiêu đề và thao tác lưu <a class="header-anchor" href="#thu-gon-vung-tieu-đe-va-thao-tac-luu" aria-label="Permalink to &quot;Thu gọn vùng tiêu đề và thao tác lưu&quot;">​</a></h3><p>Đo toolbar &lt;=64px desktop, không footer; vùng scroll không giao toolbar và cao hơn bản trước. Save luôn trong viewport ở đầu/giữa/cuối; submit form-linked button giữ payload, native validation và loading. Mobile title đọc được, back aria/keyboard, không overflow.</p><p>Kết quả: focused lint + production build/type-check pass. Workspace mock 1440×900 toolbar53px/vùng nhập729px; 1440×600 toolbar53/vùng429; 390×800 toolbar57/vùng629;390×600 toolbar57/vùng429. Không chồng ở đầu/giữa/cuối scroll, Save luôn trong viewport, textarea cuối nhìn đủ. Regression mock submit linked-form giữ payload/ID/draft, hidden-invalid focus, budget/duration optional, loading và 8 tổ hợp vi/en theme viewport pass. Đã xem ảnh desktop/mobile; không DB/API/production/commit thay đổi.</p><h3 id="thu-nho-toolbar-lan-hai" tabindex="-1">Thu nhỏ toolbar lần hai <a class="header-anchor" href="#thu-nho-toolbar-lan-hai" aria-label="Permalink to &quot;Thu nhỏ toolbar lần hai&quot;">​</a></h3><p>Đo toolbar desktop từ53px xuống41px; mobile nút44px, title2 dòng không tràn; kiểm tra nút Lưu còn trong viewport.</p><h3 id="sua-400-impact-do-đon-vi-bao-đien-tu" tabindex="-1">Sửa 400 impact do đơn vị Báo điện tử <a class="header-anchor" href="#sua-400-impact-do-đon-vi-bao-đien-tu" aria-label="Permalink to &quot;Sửa 400 impact do đơn vị Báo điện tử&quot;">​</a></h3><p>Bài báo unit bài phải qua validateNewSelection; unit cũ vẫn nhận; unit sự kiện/buổi sai cho báo phải chặn. SOCIAL_POST sai unit và duplicate service vẫn chặn. Không gọi API save trên dữ liệu demo trong QA.</p><p>Kết quả: Maven unit test 25/25 pass (PackageOfferingSimplificationTest,CampaignSeederTest,MediaPackageServiceImplTest,PackageVersionGuardTest). Bài/legacy list pass cùng validator impact/save, buổi sai và duplicate press vẫn reject. Cập nhật test đã có trên remote, không thêm file test mới. Không migration/reset/seed/DB, cần restart Business để runtime dùng validator mới; chưa xác minh HTTP với tài khoản thật. Người dùng gửi Payload phần khung, chưa có Response chi tiết để loại trừ các nguyên nhân khác.</p><h3 id="khong-tu-đong-cac-dich-vu-khac-khi-bam-xem" tabindex="-1">Không tự đóng các dịch vụ khác khi bấm Xem <a class="header-anchor" href="#khong-tu-đong-cac-dich-vu-khac-khi-bam-xem" aria-label="Permalink to &quot;Không tự đóng các dịch vụ khác khi bấm Xem&quot;">​</a></h3><p>Fixture chiều cao giới hạn để chỉ 2 hàng đầu tự mở. Click hàng3 phải giữ 3 hàng mở, pane được scroll; đóng hàng1 không đổi2/3. Resize/locale sau toggle giữ trạng thái. Chuyển package reset và auto sizing vẫn hoạt động.</p><p>Kết quả: focused ESLint pass; browser local API mock tái hiện 2 hàng tự mở + hàng3 đóng ở1440×860. Mở hàng3 giữ cả3, pane scrollHeight717/clientHeight713; đóng hàng1 giữ hàng2/3; resize/đổi locale/mobile giữ trạng thái, đổi package reset automatic như cũ. Không pageerror hoặc tràn ngang. Chỉ sửa hook UI, không API/DB; QA chỉ keep-local-only. Không commit.</p><h3 id="micro-interaction-chon-va-xem-goi" tabindex="-1">Micro-interaction chọn và xem gói <a class="header-anchor" href="#micro-interaction-chon-va-xem-goi" aria-label="Permalink to &quot;Micro-interaction chọn và xem gói&quot;">​</a></h3><p>Chọn card/ArrowDown/Up/Home/End đổi preview nhưng giữ badge current và quyền actions. Click lại card không mất focus; search/load more không bị keyboard intercept. Các hàng đã mở giữ nguyên khi toggle hàng khác. Kiểm tra light/dark, vi/en, 390px và reduced-motion, scroll độc lập, không pageerror. Kiểm tra không thêm thư viện và không đổi API/DB/export.</p><p>Browser QA local API mock: PASS ArrowDown/Up/Home/End giữ current, aria-pressed preview, CSS animation và reduced-motion, vi/en × light/dark × 390/1440, không pageerror/tràn ngang. Regression auto disclosure 2 mở/1 đóng -&gt; mở cả3, đóng riêng, resize/locale/mobile, đổi gói reset PASS. Focused ESLint và diff whitespace PASS. npm run ci bị chặn bởi 2 no-explicit-any có sẵn trong thay đổi vietnamAddressService.ts ngoài phạm vi. Không sửa các file đó. QA nằm keep-local-only.</p><p>Type-check và production build PASS; build còn warning chunk lớn đã tồn tại. CI toàn repo chưa xanh do lỗi lint ngoài phạm vi nêu trên. Không commit/push.</p><h3 id="xac-nhan-giam-hang-muc-so-luong" tabindex="-1">Xác nhận giảm hạng mục/số lượng <a class="header-anchor" href="#xac-nhan-giam-hang-muc-so-luong" aria-label="Permalink to &quot;Xác nhận giảm hạng mục/số lượng&quot;">​</a></h3><p>Backend: tăng giữ ID, giảm mặc định/chọn task giữ đúng, thiếu/sai confirmation reject, version/deployment guard; bỏ rồi thêm lại không dùng ID cũ; packageDriven chấp nhận stable selected IDs nhưng reject trùng/count/type sai. Worker giữ field/comment liên kết, hủy không xóa, retry không lặp revision và active count đúng. Web: Save impact -&gt; chọn đủ -&gt; confirm -&gt; PUT chính xác; cancel không PUT giữ form; pending/error không thành công giả; vi/en light/dark mobile keyboard. Không APPLY database demo/Atlas.</p><p>Kết quả 2026-11-06: focused ESLint, type-check và Web production build PASS (warning chunk lớn có sẵn). Browser local API mock PASS: chưa xác nhận không PUT, hủy giữ form, chọn đúng số Task mới confirm, PUT chính xác selected IDs, tăng không dialog, lỗi 409 giữ form, Escape, vi/en × light/dark × mobile/desktop. Mongo 7 QA dùng init-mongo.js hiện tại PASS: service impact/save/version/khóa triển khai, chọn Task, CANCELLED + audit + metadata, giữ brief/assignee/liên kết bình luận, chèn lỗi sau archive trước upsert -&gt; FAILED -&gt; retry READY không lặp hủy, idempotency request, tăng lại có ID mới và count kế hoạch đúng. PG trong smoke là mock, không xác minh transaction PostgreSQL thật. Không thay schema: typeMetadata.packageRemoved/packageRemovedTermsVersion trong map đã có; cancellation dùng enum DUPLICATE_OR_REPLACED đã có. Không cần migration/init/seeder mới; seeder tiếp tục tạo Task active không có marker này. Không ghi dữ liệu local demo/Atlas/production. Container QA đã dọn; artifact kiểm tra chỉ keep-local-only. Chưa restart Business/commit/push.</p><p>Regression cuối: 45/45 test Business PASS (CampaignTaskStore, CampaignPlanValidator, CampaignDeploymentProcessor, CampaignClosureService, MediaCampaignServiceImpl). Bao gồm giữ task có ordinal cao rồi tăng lại không trùng tên hoặc tái dùng ID đã hủy. File test được cập nhật đều đã theo dõi trong Git; không thêm test mới trong src.</p><h3 id="phan-biet-bo-hang-muc-va-giam-so-luong" tabindex="-1">Phân biệt bỏ hạng mục và giảm số lượng <a class="header-anchor" href="#phan-biet-bo-hang-muc-va-giam-so-luong" aria-label="Permalink to &quot;Phân biệt bỏ hạng mục và giảm số lượng&quot;">​</a></h3><p>Bỏ trọn hạng mục không có checkbox hoặc yêu cầu chọn Task; xác nhận gửi toàn bộ IDs, hủy không ghi. Giảm vẫn phải chọn đủ số Task. Hỗn hợp giữ IDs bắt buộc của hạng mục bỏ khi đổi checkbox nhóm giảm. Kiểm tra locale/theme/mobile và không đổi dữ liệu demo.</p><p>Browser local fixture PASS: bỏ trọn hạng mục không checkbox/Task list, xác nhận đủ IDs; giảm chọn đủ mới cho lưu; hỗn hợp giữ IDs bắt buộc khi thay lựa chọn; cancel null; Việt/Anh, sáng/tối, 390/1440 không overflow. Focused ESLint và diff whitespace PASS. Không thay DB.</p><p>Kiểm tra cuối phân biệt bỏ/giảm: Business 23/23 tests PASS; Web type-check + production build PASS, warning chunk lớn có sẵn. Không commit/push hoặc restart service.</p>',86)])])}const p=n(h,[["render",r]]);export{u as __pageData,p as default};
